import { GetWalletBalanceResponse, WithdrawResponse } from "../types/schema/states.js";
import { http } from "../utils/http.js";
const WALLET_ENDPOINT = 'wallet';
/**
 * Raw HTTP calls for the `/wallet` endpoint.
 */
export async function getWalletBalance(requestOptions) {
  const response = await http(requestOptions, {
    method: 'get',
    url: WALLET_ENDPOINT,
    responseType: 'json'
  });
  return GetWalletBalanceResponse.parse(response.data);
}
export async function withdrawBZZ(requestOptions, amount, address) {
  const response = await http(requestOptions, {
    method: 'post',
    url: `${WALLET_ENDPOINT}/withdraw/bzz`,
    responseType: 'json',
    params: {
      amount: amount.toPLURString(),
      address: address.toHex()
    }
  });
  return WithdrawResponse.parse(response.data).transactionHash;
}
export async function withdrawDAI(requestOptions, amount, address) {
  const response = await http(requestOptions, {
    method: 'post',
    url: `${WALLET_ENDPOINT}/withdraw/nativetoken`,
    responseType: 'json',
    params: {
      amount: amount.toWeiString(),
      address: address.toHex()
    }
  });
  return WithdrawResponse.parse(response.data).transactionHash;
}